// Package fixture implements the read-only broker.Broker against a
// JSON snapshot file so the whole pipeline runs offline. All numbers in
// the file are FAKE, generated by cmd/fixturegen.
package fixture

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"time"

	"boxpilot/internal/box"
	"boxpilot/internal/broker"
)

// File is the on-disk fixture format.
type File struct {
	AsOf time.Time `json:"as_of"` // RFC 3339 snapshot time
	// Underlying is the index quote.
	Underlying Underlying `json:"underlying"`
	Chains     []Chain    `json:"chains"`
}

// Underlying is the index quote snapshot.
type Underlying struct {
	Symbol string `json:"symbol"`
	Price  string `json:"price"` // decimal points, e.g. "5912.30"
}

// Chain is one expiry's worth of strikes.
type Chain struct {
	Expiry  string   `json:"expiry"` // YYYY-MM-DD
	Strikes []Strike `json:"strikes"`
}

// Strike carries per-strike call/put quotes; a nil contract means the
// contract is absent from the chain (exercises missing-quote filters).
type Strike struct {
	Strike int64     `json:"strike"`
	Call   *Contract `json:"call,omitempty"`
	Put    *Contract `json:"put,omitempty"`
}

// Contract is one option contract's quotes; prices are decimal points.
type Contract struct {
	Bid          string `json:"bid"`
	Ask          string `json:"ask"`
	Last         string `json:"last,omitempty"`
	Volume       int64  `json:"volume,omitempty"`
	OpenInterest int64  `json:"open_interest,omitempty"`
}

// Load reads and parses a fixture file.
func Load(path string) (*File, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read fixture %s: %w", path, err)
	}
	var f File
	if err := json.Unmarshal(raw, &f); err != nil {
		return nil, fmt.Errorf("parse fixture %s: %w", path, err)
	}
	if f.AsOf.IsZero() || f.Underlying.Symbol == "" {
		return nil, fmt.Errorf("parse fixture %s: as_of and underlying.symbol are required", path)
	}
	if _, err := box.ParsePrice(f.Underlying.Price); err != nil {
		return nil, fmt.Errorf("parse fixture %s: underlying.price: %w", path, err)
	}
	return &f, nil
}

func parseContract(c *Contract) (*broker.Contract, error) {
	if c == nil {
		return nil, nil
	}
	bid, err := box.ParsePrice(c.Bid)
	if err != nil {
		return nil, fmt.Errorf("bid %q: %w", c.Bid, err)
	}
	ask, err := box.ParsePrice(c.Ask)
	if err != nil {
		return nil, fmt.Errorf("ask %q: %w", c.Ask, err)
	}
	out := &broker.Contract{Bid: bid, Ask: ask, Volume: c.Volume, Interest: c.OpenInterest}
	if c.Last != "" {
		last, err := box.ParsePrice(c.Last)
		if err != nil {
			return nil, fmt.Errorf("last %q: %w", c.Last, err)
		}
		out.Last = last
	}
	return out, nil
}

// Broker serves the fixture as a broker.Broker. All timestamps are the
// snapshot time; no network is ever touched.
type Broker struct {
	f *File
}

// NewBroker adapts a loaded File into a broker.Broker.
func NewBroker(f *File) broker.Broker { return &Broker{f: f} }

// compile-time interface check
var _ broker.Broker = (*Broker)(nil)

func (b *Broker) GetQuote(_ context.Context, symbol string) (broker.Quote, error) {
	if symbol != b.f.Underlying.Symbol {
		return broker.Quote{}, fmt.Errorf("%w: underlying %q (fixture has %q)", broker.ErrNotFound, symbol, b.f.Underlying.Symbol)
	}
	p, err := box.ParsePrice(b.f.Underlying.Price)
	if err != nil {
		return broker.Quote{}, err
	}
	return broker.Quote{Price: p, Timestamp: b.f.AsOf}, nil
}

func (b *Broker) GetOptionChain(_ context.Context, symbol string, expiry time.Time) (broker.OptionChain, error) {
	if symbol != b.f.Underlying.Symbol {
		return broker.OptionChain{}, fmt.Errorf("%w: symbol %q", broker.ErrNotFound, symbol)
	}
	want := expiry.Format("2006-01-02")
	for _, ch := range b.f.Chains {
		if ch.Expiry != want {
			continue
		}
		out := broker.OptionChain{
			Symbol:    symbol,
			Expiry:    expiry,
			Timestamp: b.f.AsOf,
			Strikes:   make([]broker.StrikeQuotes, 0, len(ch.Strikes)),
		}
		for _, s := range ch.Strikes {
			call, err := parseContract(s.Call)
			if err != nil {
				return broker.OptionChain{}, fmt.Errorf("strike %d call: %w", s.Strike, err)
			}
			put, err := parseContract(s.Put)
			if err != nil {
				return broker.OptionChain{}, fmt.Errorf("strike %d put: %w", s.Strike, err)
			}
			out.Strikes = append(out.Strikes, broker.StrikeQuotes{Strike: s.Strike, Call: call, Put: put})
		}
		sort.Slice(out.Strikes, func(i, j int) bool { return out.Strikes[i].Strike < out.Strikes[j].Strike })
		return out, nil
	}
	return broker.OptionChain{}, fmt.Errorf("%w: expiry %s", broker.ErrNotFound, want)
}
